function getOffset(trackId) {
  const isDn = trackId?.includes('DN');
  const isLoop = trackId?.includes('LOOP') || trackId?.includes('YARD');
  if (isDn) return { lng: 0.00015, lat: 0.00010 };
  if (isLoop) return { lng: -0.00025, lat: -0.00018 };
  return { lng: 0, lat: 0 };
}

/**
 * Projects a railway chainage km onto the real track curve.
 */
export const getCoordinatesForKm = (kmValue, trackId = 'PUNE-LNL-UP') => {
  const km = Number(kmValue);
  const minKm = PUNE_LNL_TRACK_POINTS[0].km;
  const maxKm = PUNE_LNL_TRACK_POINTS[PUNE_LNL_TRACK_POINTS.length - 1].km;
  const clampedKm = Math.max(minKm, Math.min(maxKm, Number.isFinite(km) ? km : 205));

  // Find surrounding segment in calibrated track points
  let idx = 0;
  while (idx < PUNE_LNL_TRACK_POINTS.length - 2 && PUNE_LNL_TRACK_POINTS[idx + 1].km < clampedKm) {
    idx++;
  }

  const pA = PUNE_LNL_TRACK_POINTS[idx];
  const pB = PUNE_LNL_TRACK_POINTS[idx + 1];
  const span = pB.km - pA.km;
  const t = span > 0 ? (clampedKm - pA.km) / span : 0;

  const offset = getOffset(trackId);
  const lng = pA.lng + (pB.lng - pA.lng) * t + offset.lng;
  const lat = pA.lat + (pB.lat - pA.lat) * t + offset.lat;

  return [Number(lng.toFixed(6)), Number(lat.toFixed(6))];
};

/**
 * Returns a series of coordinates tracing the real railway curve between startKm and endKm.
 * Ensures possessions and maintenance stretches curve naturally with the real tracks.
 */
export const getCoordinatesRangeForKm = (startKmVal, endKmVal, trackId = 'PUNE-LNL-UP') => {
  const start = Math.min(Number(startKmVal), Number(endKmVal));
  const end = Math.max(Number(startKmVal), Number(endKmVal));
  const minKm = PUNE_LNL_TRACK_POINTS[0].km;
  const maxKm = PUNE_LNL_TRACK_POINTS[PUNE_LNL_TRACK_POINTS.length - 1].km;

  const clampedStart = Math.max(minKm, Math.min(maxKm, Number.isFinite(start) ? start : 205));
  const clampedEnd = Math.max(minKm, Math.min(maxKm, Number.isFinite(end) ? end : clampedStart + 0.5));

  const offset = getOffset(trackId);
  const result = [];

  // Start coordinate
  result.push(getCoordinatesForKm(clampedStart, trackId));

  // Intermediate points along the real track curve
  for (const pt of PUNE_LNL_TRACK_POINTS) {
    if (pt.km > clampedStart && pt.km < clampedEnd) {
      result.push([Number((pt.lng + offset.lng).toFixed(6)), Number((pt.lat + offset.lat).toFixed(6))]);
    }
  }

  // End coordinate
  result.push(getCoordinatesForKm(clampedEnd, trackId));

  return result;
};

